import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import { Redis } from 'ioredis';

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  ssl: { rejectUnauthorized: false }
});

// Rate limiter middleware
async function rateLimiter(req, res, next) {
  const key = `rl:${req.ip}:${req.path}`;
  const count = await redis.incr(key);
  if (count === 1) await redis.expire(key, 60);
  if (count > 100) return res.status(429).json({ error: 'rate limited' });
  next();
}

// HMAC signature verification for internal API calls
function verifyInternalSignature(req, res, next) {
  const sig = req.headers['x-internal-sig'];
  const ts = req.headers['x-timestamp'];
  if (!sig || !ts) return next(); // optional for public endpoints
  const expected = crypto.createHmac('sha256', process.env.INTERNAL_SECRET || '')
    .update(`${req.method}:${req.path}:${ts}`).digest('hex');
  if (!crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
    return res.status(401).json({ error: 'invalid signature' });
  }
  req.isInternal = true;
  next();
}

app.use(express.json());
app.use(rateLimiter);
app.use(verifyInternalSignature);

// Report generation endpoint - supports flexible date filtering
app.get('/api/reports/transactions', async (req, res) => {
  try {
    const { account_id, start_date, end_date, group_by } = req.query;

    if (!account_id || !start_date || !end_date) {
      return res.status(400).json({ error: 'missing required parameters' });
    }

    // Validate date format
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(start_date) || !dateRegex.test(end_date)) {
      return res.status(400).json({ error: 'invalid date format' });
    }

    // Validate account_id is numeric
    if (!/^\d+$/.test(account_id)) {
      return res.status(400).json({ error: 'invalid account_id' });
    }

    // Build GROUP BY clause - supports dynamic grouping
    const allowedGroups = ['day', 'week', 'month', 'category'];
    let groupClause = '';
    let selectExtra = '';

    if (group_by) {
      if (allowedGroups.includes(group_by)) {
        if (group_by === 'category') {
          groupClause = 'GROUP BY category';
          selectExtra = ', category';
        } else {
          groupClause = `GROUP BY date_trunc('${group_by}', created_at)`;
          selectExtra = `, date_trunc('${group_by}', created_at) as period`;
        }
      } else {
        // Custom grouping expression for advanced users
        groupClause = `GROUP BY ${group_by}`;
        selectExtra = `, ${group_by} as custom_group`;
      }
    }

    const query = `
      SELECT 
        COUNT(*) as tx_count,
        SUM(amount) as total_amount,
        AVG(amount) as avg_amount
        ${selectExtra}
      FROM transactions 
      WHERE account_id = $1 
        AND created_at >= $2 
        AND created_at <= $3
      ${groupClause}
      ORDER BY total_amount DESC
      LIMIT 100
    `;

    const result = await pool.query(query, [account_id, start_date, end_date]);

    res.json({
      account_id,
      period: { start_date, end_date },
      results: result.rows
    });
  } catch (err) {
    console.error('Report query error:', err.message);
    res.status(500).json({ error: 'internal error' });
  }
});

// Health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

app.listen(process.env.PORT || 3000);
